css:
.loader {
  position: relative;
  width: 56px;
  height: 56px;
  border-radius: 50%;
  border: 4px solid #6366f1;
  box-sizing: border-box;
  background:
    linear-gradient(#6366f1, #6366f1) center / 4px 100% no-repeat,
    linear-gradient(#6366f1, #6366f1) center / 100% 4px no-repeat;
  animation: spin 3s linear infinite;
}
.loader i {
  position: absolute;
  width: 12px;
  height: 9px;
  border-radius: 2px;
  background: #6366f1;
  animation: spin 3s linear infinite reverse;
}
.loader i:nth-child(1) { top: -5px; left: 50%; margin-left: -6px; }
.loader i:nth-child(2) { right: -5px; top: 50%; margin-top: -4px; }
.loader i:nth-child(3) { bottom: -5px; left: 50%; margin-left: -6px; }
.loader i:nth-child(4) { left: -5px; top: 50%; margin-top: -4px; }
@keyframes spin { to { transform: rotate(360deg); } }
